# Let me try to reconnect periodically. The game might end or the MCP server might restart.
import time

for attempt in range(20):
    try:
        result = await nethack.np_look()
        print(f"SUCCESS at attempt {attempt+1}!")
        print(result[:500])
        break
    except Exception as e:
        etype = type(e).__name__
        # Check if it's ConnectError or ReadTimeout
        import traceback
        tb = traceback.format_exc()
        if 'ConnectError' in tb:
            status = "Connection error"
        elif 'ReadTimeout' in tb:
            status = "Read timeout"
        else:
            status = etype
        print(f"Attempt {attempt+1}/20 at {time.strftime('%H:%M:%S')}: {status}")
        await asyncio.sleep(30)
else:
    print("Failed to reconnect after 20 attempts (10 minutes)")
"}

