async def game_call_new(tool_name, **kwargs):
    """Call a game tool on the new game server"""
    headers = {"Authorization": f"Bearer {GAME_TOKEN}"}
    async with httpx.AsyncClient(headers=headers, timeout=httpx.Timeout(60.0)) as http_client:
        async with streamable_http_client(GAME_URL, http_client=http_client) as (read, write):
            async with ClientSession(read, write) as session:
                await session.initialize()
                result = await session.call_tool(tool_name, kwargs or {})
                for content in result.content:
                    if hasattr(content, 'text'):
                        return content.text
                return str(result)

# Test the connection
try:
    result = await game_call_new("np_look")
    print(result[:500])
except Exception as e:
    print(f"Error: {type(e).__name__}")
